-- Publish editable, no-plan Word templates derived from approved parking and warehouse sources.

with source as (
  select convert_from(decode('', 'base64'), 'UTF8') as default_terms
), template_row as (
  select contract_document_template_id
  from public.contract_document_template
  where document_type = 'parking'
), inserted as (
  insert into public.contract_document_template_revision (
    contract_document_template_id, revision_no, status, generation_engine,
    template_docx_file_path, document_generation_schema, field_definitions,
    layout_definition, block_definitions, default_terms_text,
    default_restoration_criteria_text, published_at
  )
  select template_row.contract_document_template_id,
    coalesce((select max(revision_no) from public.contract_document_template_revision where contract_document_template_id = template_row.contract_document_template_id), 0) + 1,
    'published', 'document_generation', 'templates/parking/parking_lease_document_generation_v1.docx',
    '{"templateVersion":"parking_lease_docx_v1","legalTerms":"editable"}'::jsonb,
    '[{"key":"tenantName","label":"賃借人","type":"text","required":true},{"key":"propertyName","label":"建物名称","type":"text","required":true},{"key":"propertyLotAddress","label":"所在地（地番）","type":"text"},{"key":"propertyAddress","label":"所在地（住居表示）","type":"text"},{"key":"usePurpose","label":"使用目的","type":"text","required":true},{"key":"contractStartDate","label":"契約開始日","type":"date","required":true},{"key":"contractEndDate","label":"契約終了日","type":"date","required":true},{"key":"contractDurationYears","label":"契約年数","type":"number"},{"key":"parkingContractCount","label":"契約台数","type":"integer","required":true},{"key":"monthlyRentAmount","label":"月額賃料","type":"number","required":true},{"key":"monthlyRentPerSpaceAmount","label":"1台あたり月額賃料","type":"number"},{"key":"rentPaymentDue","label":"賃料支払期日","type":"text"},{"key":"dailyCalculationMethod","label":"日割計算方法","type":"text"},{"key":"depositAmount","label":"敷金","type":"number"},{"key":"depositMonths","label":"敷金月数","type":"number"},{"key":"parkingCertificateFeeAmount","label":"車庫証明発行料","type":"number"},{"key":"specialProvisions","label":"特約事項","type":"textarea"}]'::jsonb,
    '{}'::jsonb,
    '{"heading":{"enabled":true},"signature":{"enabled":true},"plan":{"enabled":false},"terms":{"enabled":true},"restoration":{"enabled":false}}'::jsonb,
    source.default_terms, '', now()
  from template_row cross join source
  where not exists (
    select 1 from public.contract_document_template_revision
    where template_docx_file_path = 'templates/parking/parking_lease_document_generation_v1.docx'
  )
  returning contract_document_template_revision_id, contract_document_template_id
), activated as (
  update public.contract_document_template template
  set active_revision_id = inserted.contract_document_template_revision_id,
      requires_plan = false,
      updated_at = now()
  from inserted
  where template.contract_document_template_id = inserted.contract_document_template_id
  returning inserted.contract_document_template_revision_id
)
update public.lease_contract_document document
set contract_document_template_revision_id = activated.contract_document_template_revision_id,
    terms_text = case when btrim(document.terms_text) = '' then source.default_terms else document.terms_text end
from activated cross join source
where document.document_type = 'parking';

update public.contract_document_template
set requires_plan = false, updated_at = now()
where document_type = 'parking';

with source as (
  select convert_from(decode('', 'base64'), 'UTF8') as default_terms
), template_row as (
  select contract_document_template_id
  from public.contract_document_template
  where document_type = 'warehouse'
), inserted as (
  insert into public.contract_document_template_revision (
    contract_document_template_id, revision_no, status, generation_engine,
    template_docx_file_path, document_generation_schema, field_definitions,
    layout_definition, block_definitions, default_terms_text,
    default_restoration_criteria_text, published_at
  )
  select template_row.contract_document_template_id,
    coalesce((select max(revision_no) from public.contract_document_template_revision where contract_document_template_id = template_row.contract_document_template_id), 0) + 1,
    'published', 'document_generation', 'templates/warehouse/warehouse_lease_document_generation_v1.docx',
    '{"templateVersion":"warehouse_lease_docx_v1","legalTerms":"editable"}'::jsonb,
    '[{"key":"tenantName","label":"賃借人","type":"text","required":true},{"key":"guarantorName","label":"連帯保証人","type":"text"},{"key":"guarantorLimitAmount","label":"連帯保証人極度額","type":"number"},{"key":"propertyName","label":"建物名称","type":"text","required":true},{"key":"propertyLotAddress","label":"所在地（地番）","type":"text"},{"key":"propertyAddress","label":"所在地（住居表示）","type":"text"},{"key":"buildingStructure","label":"構造規模","type":"text"},{"key":"floorLabel","label":"階","type":"text"},{"key":"unitNames","label":"賃貸借物件","type":"text","required":true},{"key":"leasedAreaSqm","label":"賃貸借面積㎡","type":"number"},{"key":"leasedAreaTsubo","label":"賃貸借面積坪","type":"number"},{"key":"usePurpose","label":"使用目的","type":"text","required":true},{"key":"contractStartDate","label":"契約開始日","type":"date","required":true},{"key":"contractEndDate","label":"契約終了日","type":"date","required":true},{"key":"contractDurationYears","label":"契約年数","type":"number"},{"key":"monthlyRentAmount","label":"月額賃料","type":"number","required":true},{"key":"rentPaymentDue","label":"賃料支払期日","type":"text"},{"key":"dailyCalculationMethod","label":"日割計算方法","type":"text"},{"key":"depositAmount","label":"敷金","type":"number"},{"key":"depositMonths","label":"敷金月数","type":"number"},{"key":"specialProvisions","label":"特約事項","type":"textarea"}]'::jsonb,
    '{}'::jsonb,
    '{"heading":{"enabled":true},"signature":{"enabled":true},"plan":{"enabled":false},"terms":{"enabled":true},"restoration":{"enabled":false}}'::jsonb,
    source.default_terms, '', now()
  from template_row cross join source
  where not exists (
    select 1 from public.contract_document_template_revision
    where template_docx_file_path = 'templates/warehouse/warehouse_lease_document_generation_v1.docx'
  )
  returning contract_document_template_revision_id, contract_document_template_id
), activated as (
  update public.contract_document_template template
  set active_revision_id = inserted.contract_document_template_revision_id,
      requires_plan = false,
      updated_at = now()
  from inserted
  where template.contract_document_template_id = inserted.contract_document_template_id
  returning inserted.contract_document_template_revision_id
)
update public.lease_contract_document document
set contract_document_template_revision_id = activated.contract_document_template_revision_id,
    terms_text = case when btrim(document.terms_text) = '' then source.default_terms else document.terms_text end
from activated cross join source
where document.document_type = 'warehouse';

update public.contract_document_template
set requires_plan = false, updated_at = now()
where document_type = 'warehouse';
